const known=new Map([['bergamo',[45.6944947,9.6698727]],['brescia',[45.5398022,10.2200214]],['costa di mezzate',[45.655981,9.7980483]]]);let queue=Promise.resolve(),last=0;function locate(city){const key=city.trim().toLocaleLowerCase();if(known.has(key))return Promise.resolve(known.get(key));const task=queue.then(async()=>{await new Promise(r=>setTimeout(r,Math.max(0,1100-(Date.now()-last))));last=Date.now();try{const url='https://nominatim.openstreetmap.org/search?format=json&limit=1&country=Italia&city='+encodeURIComponent(city),rows=await fetch(url).then(r=>{if(!r.ok)throw Error();return r.json();});const p=rows[0]?[Number(rows[0].lat),Number(rows[0].lon)]:null;known.set(key,p);return p;}catch{return null;}});queue=task.catch(()=>{});return task;}let current;export async function mountGroupMap(t){current?.remove();current=null;const el=document.querySelector('#groupMap');if(!el||!globalThis.L)return;const groups=JSON.parse(el.dataset.groups),status=document.querySelector('#mapStatus'),map=L.map(el,{scrollWheelZoom:false,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([45.65,9.95],10);current=map;const layer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);let success=false;layer.on('tileload',()=>{success=true;});layer.on('tileerror',()=>{if(!success&&status)status.textContent=t('mapNetworkError');});const buckets=new Map(),missing=[];for(const group of groups){const p=await locate(group.city);if(!el.isConnected)return;if(!p){missing.push(group.city);continue;}const key=p.join(',');if(!buckets.has(key))buckets.set(key,{p,groups:[]});buckets.get(key).groups.push(group);}const points=[];for(const bucket of buckets.values()){const popup=document.createElement('div'),heading=document.createElement('strong');heading.textContent=bucket.groups[0].city;popup.append(heading);const hint=document.createElement('p');hint.textContent=t('mapCityPrecision');popup.append(hint);for(const g of bucket.groups){const button=document.createElement('button');button.type='button';button.className='map-group-link';button.dataset.action='open-group';button.dataset.id=g.id;button.textContent=g.name;popup.append(button);}L.marker(bucket.p,{icon:L.divIcon({className:'group-map-marker',html:'<span>'+bucket.groups.length+'</span>',iconSize:[36,36],iconAnchor:[18,18]}),title:bucket.groups[0].city+' · '+bucket.groups.map(g=>g.name).join(', ')}).addTo(map).bindPopup(popup);points.push(bucket.p);}if(points.length>1)map.fitBounds(points,{padding:[45,45],maxZoom:13,animate:false});else if(points.length)map.setView(points[0],12);if(status)status.textContent=missing.length?t('mapMissing')+' '+[...new Set(missing)].join(', '):t('mapCityPrecision');requestAnimationFrame(()=>{if(el.isConnected&&current===map)map.invalidateSize();});}
